PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpRunning : BOOL;
END_VAR

IF Level >= 90 THEN
    PumpRunning := FALSE;
ELSIF Level <= 10 THEN
    PumpRunning := TRUE;
END_IF;

IF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
    IF PumpRunning AND Level < 90 THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;
END_IF;

END_PROGRAM

