PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR CONSTANT
    LOW_LIMIT : INT := 10;
    HIGH_LIMIT : INT := 90;
END_VAR

IF Level <= LOW_LIMIT THEN
    PumpIn := TRUE;
ELSIF Level >= HIGH_LIMIT THEN
    PumpIn := FALSE;
END_IF;

IF Level >= HIGH_LIMIT THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

IF Level >= HIGH_LIMIT THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

