PROGRAM intersection

VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR

VAR
    State : INT := 0;
    T_Green  : TON;
    T_Yellow : TON;
    T_AllRed : TON;
END_VAR

T_Green (IN := (State = 0) OR (State = 3), PT := T#2s);
T_Yellow(IN := (State = 1) OR (State = 4), PT := T#1s);
T_AllRed(IN := (State = 2) OR (State = 5), PT := T#1s);

IF State = 0 AND T_Green.Q THEN
    State := 1;
ELSIF State = 1 AND T_Yellow.Q THEN
    State := 2;
ELSIF State = 2 AND T_AllRed.Q THEN
    State := 3;
ELSIF State = 3 AND T_Green.Q THEN
    State := 4;
ELSIF State = 4 AND T_Yellow.Q THEN
    State := 5;
ELSIF State = 5 AND T_AllRed.Q THEN
    State := 0;
END_IF;

NS_G := (State = 0);
NS_Y := (State = 1);
NS_R := (State = 2) OR (State = 3) OR (State = 4) OR (State = 5);
EW_G := (State = 3);
EW_Y := (State = 4);
EW_R := (State = 0) OR (State = 1) OR (State = 2) OR (State = 5);

END_PROGRAM

PROGRAM intersection

VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
