PROGRAM elevator
VAR_INPUT
    CallUp    : BOOL;
    CallDown  : BOOL;
    DoorClosed: BOOL;
    AtTop     : BOOL;
    AtBottom  : BOOL;
END_VAR

VAR_OUTPUT
    MotorUp   : BOOL;
    MotorDown : BOOL;
END_VAR

VAR
    State     : INT := 0;
END_VAR

CASE State OF
    0:
        MotorUp   := FALSE;
        MotorDown := FALSE;
        IF CallUp AND DoorClosed AND NOT AtTop THEN
            State := 1;
        END_IF;

    1:
        IF AtTop OR NOT DoorClosed THEN
            MotorUp   := FALSE;
            MotorDown := FALSE;
            IF AtTop THEN
                State := 2;
            ELSE
                State := 0;
            END_IF;
        ELSE
            MotorUp   := TRUE;
            MotorDown := FALSE;
        END_IF;

    2:
        MotorUp   := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed AND NOT AtBottom THEN
            State := 3;
        END_IF;

    3:
        IF AtBottom OR NOT DoorClosed THEN
            MotorUp   := FALSE;
            MotorDown := FALSE;
            IF AtBottom THEN
                State := 0;
            ELSE
                State := 2;
            END_IF;
        ELSE
            MotorUp   := FALSE;
            MotorDown := TRUE;
        END_IF;

    ELSE
        MotorUp   := FALSE;
        MotorDown := FALSE;
        State     := 0;
END_CASE;

IF NOT DoorClosed THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
END_IF;

IF AtTop THEN
    MotorUp := FALSE;
END_IF;

IF AtBottom THEN
    MotorDown := FALSE;
END_IF;

IF MotorUp AND MotorDown THEN
    MotorUp   := FALSE;
    MotorDown := FALSE;
END_IF;

END_PROGRAM

