PROGRAM batch_reactor

VAR_INPUT
    StartBatch : BOOL;
    Level      : INT;
    Temp       : INT;
    EStop      : BOOL;
END_VAR

VAR_OUTPUT
    FillValve  : BOOL;
    Heater     : BOOL;
    Agitator   : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State      : INT := 0;
    ReactTimer : TON;
END_VAR

VAR CONSTANT
    LVL_HIGH   : INT := 80;
    LVL_LOW    : INT := 5;
    TEMP_SET   : INT := 100;
    LIQ_MIN    : INT := 10;
END_VAR

ReactTimer(IN := (State = 3) AND EStop, PT := T#3s);

IF NOT EStop THEN
    State      := 0;
    FillValve  := FALSE;
    Heater     := FALSE;
    Agitator   := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0:
            FillValve  := FALSE;
            Heater     := FALSE;
            Agitator   := FALSE;
            DrainValve := FALSE;
            IF StartBatch THEN
                State := 1;
            END_IF;

        1:
            DrainValve := FALSE;
            Heater     := FALSE;
            Agitator   := FALSE;
            FillValve  := TRUE;
            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State     := 2;
            END_IF;

        2:
            FillValve  := FALSE;
            DrainValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater   := TRUE;
                Agitator := TRUE;
            ELSE
                Heater   := FALSE;
                Agitator := FALSE;
            END_IF;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;

        3:
            FillValve  := FALSE;
            DrainValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater   := TRUE;
                Agitator := TRUE;
            ELSE
                Heater   := FALSE;
                Agitator := FALSE;
            END_IF;
            IF ReactTimer.Q THEN
                Heater     := FALSE;
                Agitator   := FALSE;
                State      := 4;
            END_IF;

        4:
            FillValve  := FALSE;
            Heater     := FALSE;
            Agitator   := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State      := 0;
            END_IF;

        ELSE
            State      := 0;
            FillValve  := FALSE;
            Heater     := FALSE;
            Agitator   := FALSE;
            DrainValve := FALSE;
    END_CASE;

    IF (Heater OR Agitator) AND (Level < LIQ_MIN) THEN
        Heater   := FALSE;
        Agitator := FALSE;
    END_IF;

    IF FillValve AND DrainValve THEN
        FillValve  := FALSE;
        DrainValve := FALSE;
    END_IF;

END_IF;

END_PROGRAM

