PROGRAM tank_cycle

VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    HIGH : INT := 90;
    LOW : INT := 10;
    DummyTimer : TON;
END_VAR

DummyTimer(IN := FALSE, PT := T#1s);

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSE
    CASE State OF
        0:
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND (Level < HIGH) THEN
                State := 1;
            END_IF;

        1:
            IF Level >= HIGH THEN
                Pump := FALSE;
                Valve := FALSE;
                State := 2;
            ELSE
                Pump := TRUE;
                Valve := FALSE;
            END_IF;

        2:
            IF Level <= LOW THEN
                Pump := FALSE;
                Valve := FALSE;
                State := 0;
            ELSE
                Pump := FALSE;
                Valve := TRUE;
            END_IF;

    ELSE
        State := 0;
        Pump := FALSE;
        Valve := FALSE;
    END_CASE;

    IF Level >= HIGH THEN
        Pump := FALSE;
    END_IF;

    IF Level <= LOW THEN
        Valve := FALSE;
    END_IF;

    IF Pump AND Valve THEN
        Pump := FALSE;
        Valve := FALSE;
    END_IF;

END_IF;

END_PROGRAM

PROGRAM tank_cycle

VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    HIGH : INT := 90;
    LOW : INT := 10;
    SafePump : BOOL;
    SafeValve : BOOL;
END_VAR

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSE
    CASE State OF
        0:
            IF StartCycle AND (Level < HIGH) THEN
                State := 1;
            END_IF;
        1:
            IF Level >= HIGH THEN
                State := 2;
            END_IF;
        2:
            IF Level <= LOW THEN
                State := 0;
            END_IF;
        ELSE
            State := 0;
    END_CASE;

    SafePump := FALSE;
    SafeValve := FALSE;

    IF State = 1 THEN
        SafePump := TRUE;
        SafeValve := FALSE;
    ELSIF State = 2 THEN
        SafePump := FALSE;
        SafeValve := TRUE;
    ELSE
        SafePump := FALSE;
        SafeValve := FALSE;
    END_IF;

    IF SafePump AND SafeValve THEN
        SafePump := FALSE;
        SafeValve := FALSE;
    END_IF;

    IF SafePump AND (Level >= HIGH) THEN
        SafePump := FALSE;
    END_IF;

    IF SafeValve AND (Level <= LOW) THEN
        SafeValve := FALSE;
    END_IF;

    Pump := SafePump;
    Valve := SafeValve;
END_IF;

END_PROGRAM

