    State    : INT := 0;
    tPurge   : TON;
    tIgn     : TON;
    Healthy  : BOOL;
END_VAR

tPurge(IN := (State = 1), PT := T#3s);
tIgn(IN := (State = 2), PT := T#2s);

Healthy := EStop AND NOT StopPB;

IF NOT Healthy THEN
    State    := 0;
    Fan      := FALSE;
    Fuel     := FALSE;
    Ignition := FALSE;
ELSE
    CASE State OF
        0:
            Fan      := FALSE;
            Fuel     := FALSE;
            Ignition := FALSE;
            IF StartPB THEN
                State := 1;
            END_IF;

        1:
            Fan      := TRUE;
