            Ignition := FALSE;
            IF tPurge.Q THEN
                State := 2;
            END_IF;

        2:
            Fan      := TRUE;
            Fuel     := TRUE;
            Ignition := TRUE;
            IF tIgn.Q THEN
                IF Flame THEN
                    State := 3;
                ELSE
                    State    := 0;
                    Fan      := FALSE;
                    Fuel     := FALSE;
                    Ignition := FALSE;
                END_IF;
            END_IF;

        3:
            Fan      := TRUE;
            Fuel     := TRUE;
            Ignition := FALSE;
            IF NOT Flame THEN
                State    := 0;
                Fan      := FALSE;
                Fuel     := FALSE;
                Ignition := FALSE;
            END_IF;

        ELSE
            State    := 0;
            Fan      := FALSE;
            Fuel     := FALSE;
            Ignition := FALSE;
    END_CASE;
END_IF;

