PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
END_VAR

IF State = 1 AND OpenLimit THEN
    State := 0;
END_IF;

IF State = 2 AND (CloseLimit OR Obstruction) THEN
    State := 0;
END_IF;

IF State = 0 THEN
    IF OpenCmd AND NOT OpenLimit THEN
        State := 1;
    ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
        State := 2;
    END_IF;
END_IF;

MotorOpen := (State = 1) AND NOT OpenLimit;
MotorClose := (State = 2) AND NOT CloseLimit AND NOT Obstruction;

IF MotorOpen AND MotorClose THEN
    MotorOpen := FALSE;
    MotorClose := FALSE;
    State := 0;
END_IF;

END_PROGRAM

