    Count := 0;
    Done := FALSE;
ELSE
    IF Trigger AND NOT PrevTrigger THEN
        IF Count < N THEN
            Count := Count + 1;
        END_IF;
    END_IF;
    IF Count >= N THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM
